from _build_muddaththir_74_head import *  # noqa: F401,F403


V = {
1: ('يا أيها المدثر در بستر آرمیده', 'نمونه می‌گوید ای در بستر خواب آرمیده و جامه بر سر کشیده مخاطب پیامبر است و برای این آرمیدن احتمالاتی گفته‌اند از جمله ناراحتی پیامبر از مشورت سران قریش که او را ساحر خواندند و به خانه آمد و در بستر آرمید و از جمله روایت جابر از آغاز وحی و نمونه احتمال نخست را مناسب‌تر می‌داند و پیام این خطاب پایان وقت خواب و آغاز قیام و تبلیغ است', ''),
2: ('قم فأنذر برخیز و بیم ده', 'نمونه می‌گوید برخیز و انذار کن و جهانیان را بیم ده که وقت خواب و استراحت گذشته و زمان قیام و تبلیغ رسیده است و تکیه بر انذار با آنکه پیامبر بشیر و نذیر هر دو است از آن روست که انذار در آغاز کار تأثیر عمیق‌تری در بیدارکردن ارواح خفته دارد و حذف متعلق انذار عمومیت هشدار درباره شرک و ظلم و عذاب دنیا و آخرت را می‌رساند', ''),
3: ('وربك فكبر پروردگارت را بزرگ بشمار', 'نمونه می‌گوید تنها پروردگارت را بزرگ بشمار و تکبیر تنها گفتن الله اکبر نیست بلکه بزرگ شمردن خدا در اعتقاد و عمل و سخن است و او را از هر نقص منزه و برتر از آن دانستن که در توصیف بگنجد و تقدیم کلمه رب بر کبّر دلیل انحصار توحید است و نخستین دستور پس از قیام اصلاح رابطه با خدا و محو آثار شرک و بت‌پرستی است', ''),
4: ('وثيابك فطهر لباست را پاک کن', 'نمونه می‌گوید لباست را پاک کن و لباس ممکن است کنایه از عمل انسان باشد که چون پوشش اوست یا قلب و روح یا همان لباس ظاهر که پاکیزگی آن نشانه شخصیت و تربیت است و در روایت امام صادق علیه‌السلام معنای آیه کوتاه‌کردن لباس دانسته شده تا دامان بر زمین کشیده و آلوده نشود و جمع میان این معانی ممکن است و پاکی رهبر شرط نفوذ سخن اوست', ''),
5: ('والرجز فاهجر از پلیدی بپرهیز', 'نمونه می‌گوید از پلیدی و رجز دوری و هجرت کن و رجز بت‌ها و گناه و هر آلودگی اعتقادی و عملی را دربر می‌گیرد و این دستور پس از تطهیر لباس پاکی باطن و رفتار را کامل می‌کند و رهبر دعوت باید از هر آنچه مردم را از او می‌راند و دعوت را آلوده می‌کند فاصله بگیرد تا الگوی پاکی برای پیروان باشد', ''),
6: ('ولا تمنن تستكثر منت مگذار', 'نمونه می‌گوید در برابر کارهایی که برای خدا انجام می‌دهی منت مگذار و آن را بزرگ و فزون مشمار و این دستور اخلاص دعوت است که پیامبر خدمت خود را به حساب مردم نگذارد و چشم‌داشت افزون‌طلبانه نداشته باشد و هر که کار خیر را برای خدا کند نباید آن را سرمایه منت بر خلق سازد و این فرمان حلقه اخلاقی برنامه آمادگی پیامبر است', ''),
7: ('ولربك فاصبر برای پروردگارت شکیبا باش', 'نمونه می‌گوید به خاطر پروردگارت شکیبایی کن و این هفتمین و آخرین دستور از فرمان‌های آمادگی است که صبر باید برای خدا باشد نه برای نام و آوازه و تحمل آزار دعوت با این نیت معنا می‌یابد و مجموعه این فرمان‌ها از قیام و انذار تا توحید و طهارت و اخلاص و صبر منشور آغازین حرکت پیامبر را می‌سازد', ''),
8: ('فإذا نقر في الناقور کوبیدن ناقور', 'نمونه می‌گوید هنگامی که در صور دمیده شود و نقر در ناقور کنایه از همان نفخ صور و زنده‌شدن مردگان است و پس از فرمان‌های آمادگی صحنه قیامت گشوده می‌شود تا انذار پیامبر پشتوانه اخروی خود را نشان دهد و این دگرگونی ناگهانی جهان سرآغاز بخش تهدید تکذیب‌کنندگان در سوره است', 'نقر در ناقور کنایه از زنده کردن مردگان در قیامت و احضار آنان برای حساب‌رسی است و نقر به معنای کوبیدن و ناقور چیزی است که به آن می‌کوبند تا صدا کند و جمله شرطی است و جزای آن فذلک يومئذ يوم عسير است'),
9: ('فذلك يومئذ يوم عسير روز سخت', 'نمونه می‌گوید آن روز روز سختی است و سختی آن از هول حساب و جزا و فروپاشی عالم است و این تعبیر کوتاه شدت قیامت را بدون تفصیل می‌نشاند و سپس آیه بعد روشن می‌کند که این دشواری به‌ویژه بر کافران سنگینی می‌کند و مؤمنان از رحمت خدا برخوردارند و گذار از فرمان‌های آمادگی به تهدید با همین تصویر فشرده انجام می‌شود', 'اشاره ذلک به زمان نقر در ناقور است و يومئذ روز بازگشت خلائق به سوی خدا برای حساب و جزاست و جمله غیر یسير صفت دیگری برای یوم است که سختی آن روز را تأکید می‌کند که از یک جهت و دو جهت نیست بلکه از هر جهت دشوار است'),
10: ('على الكافرين غير يسير بر کافران آسان نیست', 'نمونه می‌گوید آن روز برای کافران آسان نیست و تعبیر غیر يسر تأکید مضاعف بر دشواری است که هیچ راه آسانی برای آنان نمی‌گذارد و تخصیص سختی به کافران از آن روست که مؤمن در آن روز به فضل خدا در امنیت است و این تقابل از همان آغاز سوره دو گروه مؤمن آماده و کافر تکذیب‌کننده را برابر هم می‌نشاند', ''),
11: ('ذرني ومن خلقت وحيدا تنها آفریده‌شده', 'نمونه می‌گوید مرا با کسی که او را تنها آفریدم واگذار و این آیات درباره ولید بن مغیره مخزومی از سران قریش نازل شده است و وحیدا می‌تواند وصف خالق باشد که من به تنهایی او را آفریدم یا وصف مخلوق که تنها و بی‌مال و فرزند به دنیا آمد یا تکرار استهزایی لقب خود ولید که خود را وحید و بی‌نظیر عرب می‌خواند و نمونه تفسیر نخست را مناسب‌تر می‌داند', 'وحیدا حال از فاعل خلقت است و معنا این است که مرا با آن کس که خلقش کردم در حالی که احدی با من در خلقت وی شرکت نداشت واگذار و روایات بسیار زیادی وارد شده که این جمله تا بیست آیه بعدش همه درباره ولید بن مغیره نازل شده است'),
12: ('وجعلت له مالا ممدودا مال گسترده', 'نمونه می‌گوید من برای او مال گسترده و فراوان قرار دادم و ممدود در اصل به معنای کشیده است و ناظر به گستردگی اموال او از نظر حجم و مکان و زمان است و گفته‌اند اموالش از مکه تا طائف شتران و اسب‌ها و مستغلات فراوان و صد هزار دینار طلا بود و باغ‌هایی داشت که غله یکی تمام نشده دیگری می‌رسید و همه این معانی در ممدود جمع است', 'مال ممدود یعنی مالی گسترده و یا مالی که به مدد نتایج و فوایدش امتداد یافته و این نعمت در کنار فرزندان و تمهید کامل زندگی ولید قرار گرفت تا کفران او با وجود این همه بخشش آشکارتر شود'),
13: ('وبنين شهودا فرزندان حاضر', 'نمونه می‌گوید و فرزندانی برای او قرار دادم که همواره نزد او حاضر و در خدمتش آماده‌اند و حضورشان مایه انس و راحت او بود و هرگز به سبب تنگی معیشت ناچار به سفر به نقاط دوردست نشدند تا پدر در رنج دوری بماند و در بعضی روایات شمار فرزندان او ده تن آمده است و این نیروی انسانی حاضر دومین نعمت بزرگ ولید پس از مال گسترده بود', 'بنین شهودا یعنی پسرانی حاضر که آنان را پیش روی خود می‌بیند که می‌خرامند و از آنان در رسیدن به هدف‌های خود کمک می‌گیرد و این جمله عطف بر کلمه مالا در سیاق شمارش نعمت‌هاست'),
14: ('ومهدت له تمهيدا وسایل فراهم‌شده', 'نمونه می‌گوید وسایل زندگی او را از هر نظر فراهم ساختم و تمهید از ماده مهد در اصل محل آماده برای کودک چون گاهواره است و سپس به هر وسیله استراحت و پیشرفت و مقام و موقعیت اجتماعی گفته می‌شود و معنای وسیع آن انواع مواهب حیات را دربر می‌گیرد و ولید نه فقط مال و فرزند بلکه از نظر جاه و جسم و جامعه غرق در نعمت بود', 'کلمه تمهید به معنای تهیه است که به طور مجاز در مورد گستردگی مال و جاه و روبه‌راهی زندگی استعمال می‌شود و از نعمت‌هایی است که برای ولید آماده شده بود'),
15: ('ثم يطمع أن أزيد طمع فزونی', 'نمونه می‌گوید با این همه مال و نعمت باز هم طمع دارد که بر نعمت‌های او بیفزایم و این خصلت منحصر به ولید نبود بلکه همه دنیاپرستان چنین‌اند که عطش آن‌ها هرگز فرو نمی‌نشیند و اگر هفت اقلیم را زیر نگین آنان قرار دهند باز در بند اقلیمی دیگرند و طمع پس از کفران چهره سوم شخصیت ولید در این بخش است', ''),
16: ('كلا إنه كان لآياتنا عنيدا عناد با آیات', 'نمونه می‌گوید هرگز چنین نخواهد شد که بر نعمتش بیفزایم چرا که او نسبت به آیات ما دشمنی آگاهانه می‌ورزید و عنید به گفته بعضی مخالفتی است که انسان حقانیت چیزی را درک کند و با آن مخالفت برخیزد و ولید مصداق روشن آن بود که با شناخت شیرینی و برتری قرآن آن را سحر نامید و تعبیر کان استمرار و همیشگی‌بودن عناد او را می‌رساند', 'کلا طمع و توقع او را رد می‌کند و جمله انه کان علت این رد را بیان می‌کند و عنید معاندی است که به عناد خود و آنچه دارد مباهات هم می‌کند'),
17: ('سأرهقه صعودا گردنه سخت', 'نمونه می‌گوید ما به زودی او را مجبور می‌کنیم از قله صعب‌العبور زندگی بالا رود و سپس او را از فراز آن به زیر می‌افکنیم و ارهاق تحمیل کار سخت و مبتلا ساختن به عذاب است و صعود مکان مرتفع دشوارگذر است و بعضی آن را کوهی از آتش در جهنم دانسته‌اند که او را وامی‌دارند از آن بالا رود و این سرنوشت دردناک ولی در یک تعبیر کوتاه آمده است', ''),
18: ('إنه فكر وقدر اندیشید و سنجید', 'نمونه می‌گوید ولید درباره قرآن اندیشید و اندازه گرفت تا در برابر پرسش قریش داوری کند و این فکر و تقدیر نه برای یافتن حق بلکه برای ساختن برچسبی بود که دعوت را خنثی کند و داستان آن در شأن نزول سوره آمده که ولید پس از شنیدن قرآن آن را شیرین و برتر از هر سخن دانست اما زیر فشار ابوجهل به داوری دیگری روی آورد', ''),
19: ('فقتل كيف قدر مرگ بر او باد', 'نمونه می‌گوید مرگ بر او باد چگونه اندازه گرفت و این نفرین و تعجب از تقدیر و سنجش مغرضانه اوست که عقل و وجدان خود را در خدمت عناد گذاشت و قرآن این داوری را مرگ‌بار می‌خواند زیرا سخن او سرنوشت قریش را در برابر دعوت رقم زد و برچسب سحر از همین سنجش زاده شد و تکرار آن در آیه بعد شدت انحراف را نشان می‌دهد', ''),
20: ('ثم قتل كيف قدر باز مرگ بر او', 'نمونه می‌گوید و باز هم مرگ بر او باد با آن اندازه‌گیری‌اش و تکرار نفرین نشانه ژرفای انحراف داوری ولید است که پس از شناخت حق و اعتراف به برتری قرآن به خاطر جایگاه اجتماعی خود راه دیگری برگزید و قرآن این دوگانگی شناخت و انتخاب را مرگ وجدان می‌خواند و این آیه حلقه دوم زنجیره روان‌شناسی عناد اوست', ''),
21: ('ثم نظر سپس نگاه کرد', 'نمونه می‌گوید آنگاه ولید نگاهی کرد و این نگاه مرحله دیگری از فرایند داوری اوست که پس از فکر و تقدیر برای یافتن برچسب و آماده‌کردن پاسخ به اطراف نگریست و قرآن مراحل عناد او را گام‌به‌گام تصویر می‌کند از اندیشه و سنجش تا نگاه و چهره درهم‌کشیدن و پشت‌کردن و این تصویر تدریجی نشان می‌دهد انکار او ناگهانی و ناآگاهانه نبود بلکه ساخته و پرداخته شد', ''),
22: ('ثم عبس وبسر چهره درهم کشید', 'نمونه می‌گوید سپس چهره درهم کشید و روی ترش کرد و عبس و بسر نمود بیرونی نپذیرفتن حق در چهره ولید است که پیش از زبان سخن گفت و این حالت چهره نشان کشمکش درونی اوست میان آنچه از قرآن دریافته بود و آنچه منافع و جایگاهش اقتضا می‌کرد و سرانجام کفه استکبار سنگین شد و چهره عبوس پیش‌درآمد پشت‌کردن عملی او گشت', ''),
23: ('ثم أدبر واستكبر پشت کرد و تکبر ورزید', 'نمونه می‌گوید پس پشت کرد و تکبر ورزید و ادبار و استکبار پایان فرایند عناد ولید است که از فکر آغاز شد و به عمل رسید و پشت‌کردن او تنها جسمانی نبود بلکه روی‌گردانی از حق شناخته‌شده بود و تکبر مانع شد اعتراف درونی خود به عظمت قرآن را به زبان آورد و این آیه آستانه صدور حکم سحر از زبان اوست', ''),
24: ('فقال إن هذا إلا سحر يؤثر سحر نقل‌شده', 'نمونه می‌گوید سرانجام گفت این قرآن جز سحری نیست که از پیشینیان نقل و آموخته شده است و سحر يؤثر یعنی جادویی که از دیگران فرا گرفته شده و این برچسب پس از آن همه تردید و سنجش انتخاب شد چون ولید اثر قرآن در جداکردن خویشان از یکدیگر را دید و آن را به سحر نسبت داد و این جمله محصول نهایی زنجیره عناد اوست', ''),
25: ('إن هذا إلا قول البشر سخن بشر', 'نمونه می‌گوید و گفت این جز سخن بشر نیست و این انکار صریح وحی و بشری‌خواندن قرآن است در حالی که خود او گفته بود این سخن نه شبیه سخن انسان‌هاست و نه سخن جن و شیرینی و طراوت و برتری بی‌مانند دارد و همین تناقض میان دریافت درونی و گفتار بیرونی ولید حکم سقر را در آیه بعد بر او رقم زد', ''),
26: ('سأصليه سقر درآوردن به سقر', 'نمونه می‌گوید به زودی او را به سقر درمی‌آوریم و سقر نامی از نام‌های آتش دوزخ است که گوینده سخن «قول البشر» را در خود فرو می‌برد و این حکم پاسخ مستقیم به جمله ولید است که قرآن را سخن بشر خواند و نمونه در این پیوند نشان می‌دهد کیفر با جرم تناسب دارد و انکار وحی سرانجامش ورود به آتشی است که دو آیه بعد وصف آن می‌آید', ''),
27: ('وما أدراك ما سقر چه دانی سقر چیست', 'نمونه می‌گوید و تو چه می‌دانی سقر چیست و این پرسش تعظیمی برای نشان‌دادن هول و عظمت ناشناخته آن آتش است که فراتر از ادراک و تجربه بشری است و تعبیر «ما أدراک» در قرآن برای امور عظیمی می‌آید که حقیقتشان جز با مشاهده دانسته نمی‌شود و این آیه مقدمه وصف سه‌گانه سقر در آیات بعد قرار می‌گیرد', ''),
28: ('لا تبقي ولا تذر باقی نمی‌گذارد', 'نمونه می‌گوید سقر نه چیزی باقی می‌گذارد و نه کسی را رها می‌کند و همه وجود گنهکار را فرا می‌گیرد و هیچ‌کس و هیچ عضوی از قلم مجازات نمی‌افتد و این وصف نهایت شمول و استمرار آن آتش است که نه نابود می‌کند تا رهایی باشد و نه رها می‌کند تا آسودگی و دو آیه بعد اثر آن بر پوست و نگهبانان آن را کامل می‌کند', ''),
29: ('لواحة للبشر سیاه‌کننده پوست', 'نمونه می‌گوید سقر پوست بدن را سیاه و دگرگون می‌کند و لواحة از لوح به معنای سوزاندن و سیاه‌کردن سطح است و بشره پوست ظاهری انسان است که نخستین برخورد آتش با آن است و این تصویر حسّی اثر آتش را از شمول کلی آیه پیش به نمود بدنی می‌رساند و سرانجام بدن همان انسانی را می‌سوزاند که با زبانش وحی را انکار کرده بود', ''),
30: ('عليها تسعة عشر نوزده نگهبان', 'نمونه می‌گوید بر آن آتش نوزده تن یا نوزده گروه گمارده شده‌اند و ذکر این عدد سبب گفت‌وگو و استهزای مشرکان شد که آن را کم شمردند و گفتند در برابر هر یک ده نفر می‌گذاریم و این پندار از نادانی آنان نسبت به قدرت فرشتگان بود که چند تن از آنان مأمور هلاکت شهرهای قوم لوط شدند و آیه بعد حکمت این عدد را پاسخ می‌گوید', ''),
31: ('وما جعلنا أصحاب النار إلا ملائكة عدد نوزده و آزمون', 'نمونه می‌گوید مأموران دوزخ را جز فرشتگان قرار ندادیم و تعداد آنان را جز برای آزمایش کافران معین نکردیم تا اهل کتاب یقین پیدا کنند و ایمان مؤمنان افزوده شود و اهل کتاب و مؤمنان تردید نورزند و بیماردلان و کافران بگویند خدا از این توصیف چه منظوری دارد و لشکریان پروردگار را جز او کسی نمی‌داند و این جز تذکری برای انسان‌ها نیست و این طولانی‌ترین آیه سوره پاسخ کامل به استهزای عدد نوزده است', ''),
32: ('كلا والقمر سوگند به ماه', 'نمونه می‌گوید سوگند به ماه و کلا رد انکار کافران است و پس از آیه تذکره بخش پایانی سوره با سوگندهایی آغاز می‌شود که عظمت سقر و حتمیت هشدار را اثبات می‌کند و ماه و شب و صبح نشانه‌هایی از نظم آفرینش‌اند که انسان هر روز می‌بیند و سوگند به آن‌ها زمینه تصدیق خبر نادیده قیامت را فراهم می‌کند', ''),
33: ('والليل إذ أدبر شب چون برود', 'نمونه می‌گوید و سوگند به شب هنگامی که پشت کند و برود و ادبار شب رفتن تاریکی و گشوده‌شدن راه صبح است و این دگرگونی روزانه شب نمونه‌ای محسوس از توان خدا بر برانگیختن و جزاست و در کنار سوگند به ماه و صبح زنجیره‌ای از نشانه‌های زمان را می‌سازد که پایان هر یک آغاز دیگری است و مرگ و بعث نیز چنین‌اند', ''),
34: ('والصبح إذا أسفر صبح چون روشن شود', 'نمونه می‌گوید و سوگند به صبح هنگامی که روشن شود و پرده برگیرد و اسفار به معنای روشن‌شدن و آشکارگشتن است و صبح پس از شب تصویری از آشکارشدن حق پس از پنهان‌بودن آن است و سوگندهای سه‌گانه ماه و شب و صبح با حرکت نور و تاریکی ذهن شنونده را برای پذیرش بزرگی سقر و راستی هشدار آماده می‌کند', ''),
35: ('إنها لإحدى الكبر یکی از بزرگ‌ترین‌ها', 'نمونه می‌گوید آن سقر یکی از بزرگ‌ترین‌هاست و کبر جمع کبری یا صفت بزرگ‌ترین بلاها و نشانه‌هاست و ضمیر به سقر برمی‌گردد که از بزرگ‌ترین آیات هول‌آور قیامت است و این جمله نتیجه سوگندهای پیشین است که سقر نه افسانه‌ای برای ترساندن بلکه واقعیتی عظیم در نظام جزاست و دو آیه بعد کارکرد آن را بیم‌دهندگی برای همه بشر می‌داند', ''),
36: ('نذيرا للبشر بیم‌دهنده بشر', 'نمونه می‌گوید سقر و خبر آن بیم‌دهنده‌ای برای همه بشر است و هیچ گروه و قومی از این هشدار بیرون نیست و همین عمومیت با آغاز سوره پیوند دارد که پیامبر مأمور انذار جهانیان شد و اکنون ابزار آن انذار یعنی خبر سقر به همه انسان‌ها عرضه می‌شود و اختیار پاسخ در آیه بعد به خود انسان واگذار می‌گردد', ''),
37: ('لمن شاء منكم أن يتقدم أو يتأخر پیشی یا واپس', 'نمونه می‌گوید برای هر کس از شما که بخواهد پیشی گیرد یا واپس بماند و این تقدم و تأخر اختیار انسان در مسیر ایمان و عمل است که می‌تواند به سوی حق پیش رود یا عقب بماند و هشدار سقر به معنای جبر نیست بلکه راه هر دو سوی گشوده است و نتیجه انتخاب در آیه بعد با گروبودن هر نفس در برابر کرده خویش کامل می‌شود', ''),
38: ('كل نفس بما كسبت رهينة هر نفس در گرو', 'نمونه می‌گوید هر نفسی در گرو و گروگان آن چیزی است که کسب کرده است و رهینه بودن یعنی آزادی انسان در قیامت وابسته به عمل اوست و اعمال نیک گرو را می‌گشاید و گناه آن را سنگین می‌کند و این اصل مسئولیت فردی پایه صحنه گفت‌وگوی بهشتیان و دوزخیان در آیات بعد است که هیچ‌کس بار دیگری را برنمی‌دارد', ''),
39: ('إلا أصحاب اليمين مگر اصحاب یمین', 'نمونه می‌گوید مگر اصحاب یمین که از گرو عمل رسته‌اند و آنان مؤمنانی‌اند که نامه عملشان به دست راست داده می‌شود و با ایمان و عمل صالح زنجیر گرو را گشوده‌اند و این استثنا گروه نجات‌یافته را روبه‌روی مجرمان می‌نشاند تا در آیات بعد از باغ‌های بهشت سرنوشت آنان را بپرسند و اعتراف چهارگانه دوزخیان آشکار شود', ''),
40: ('في جنات يتساءلون در باغ‌ها می‌پرسند', 'نمونه می‌گوید اصحاب یمین در باغ‌های پر نعمت بهشت‌اند و از یکدیگر می‌پرسند و از این آیه استفاده می‌شود رابطه میان بهشتیان و دوزخیان به کلی قطع نمی‌شود و بهشتیان می‌توانند از عالم خود وضع دوزخیان را ببینند و با آنان گفت‌وگو کنند و این گفت‌وگو هم نعمت آگاهی برای رستگاران است و هم حسرتی افزوده برای مجرمان', ''),
41: ('عن المجرمين پرسش از گنهکاران', 'نمونه می‌گوید و از گنهکاران می‌پرسند و این پرسش کوتاه مقدمه پرسش اصلی آیه بعد است که چه چیز شما را به سقر درآورد و تعبیر مجرمین به جای نام اشخاص نشان می‌دهد موضوع داوری جرم و کرده آنان است نه هویت قومی و قبیله‌ای و پاسخ چهارگانه آنان در آیات بعد اعترافی است که از زبان خودشان شنیده می‌شود', ''),
42: ('ما سلككم في سقر چه شما را به سقر آورد', 'نمونه می‌گوید به آنان می‌گویند چه چیز شما را به سقر درآورد و این پرسش سرآغاز اعتراف دوزخیان است که به چهار گناه بزرگ خود اقرار می‌کنند و نکته آن است که در قیامت دیگر جای انکار نیست و خود مجرمان علت فرجام خویش را برمی‌شمارند و این اعتراف ساختار تربیتی سوره را از تهدید ولید تا سرنوشت عام گنهکاران کامل می‌کند', ''),
43: ('قالوا لم نك من المصلين از نمازگزاران نبودیم', 'نمونه می‌گوید گفتند ما از نمازگزاران نبودیم و این نخستین اعتراف از چهار اعتراف است که نماز اگر خوانده می‌شد آنان را به یاد خدا می‌انداخت و از فحشا و منکر بازمی‌داشت و به صراط مستقیم دعوت می‌کرد و ترک نماز در اینجا نماد گسستن پیوند با خالق است و نشان می‌دهد کفار همان‌گونه که به اصول مکلف‌اند به فروع نیز مکلف‌اند', ''),
44: ('ولم نك نطعم المسكين مسکین اطعام نمی‌کردیم', 'نمونه می‌گوید و ما مسکین را اطعام نمی‌کردیم و اطعام مسکین هر گونه کمک به نیازهای ضروری نیازمندان از خوراک و پوشاک و مسکن است و مفسران تصریح کرده‌اند مراد زکات واجب است زیرا ترک انفاق مستحب سبب ورود در دوزخ نمی‌شود و این آیه پیوند عبادت فردی و مسئولیت اجتماعی را نشان می‌دهد که ترک نماز و ترک اطعام در کنار هم آمده‌اند', ''),
45: ('وكنا نخوض مع الخائضين فرو رفتن در باطل', 'نمونه می‌گوید ما پیوسته با فرورونده‌گان در باطل فرو می‌رفتیم و خوض در اصل ورود در آب و در قرآن غالبا ورود در مطالب باطل است و معنای گسترده آن همراهی با مجالس استهزای آیات خدا و ترویج بدعت و غیبت و لهو را دربر می‌گیرد و در آیه بیشتر نظر بر مجالس تضعیف دین و ترویج کفر است که همرنگی با آن انسان را شریک جرم می‌کند', ''),
46: ('وكنا نكذب بيوم الدين روز جزا انکار می‌کردیم', 'نمونه می‌گوید و ما همواره روز جزا را تکذیب می‌کردیم و انکار معاد تمام ارزش‌های الهی و اخلاقی را متزلزل می‌سازد و انسان را برای ارتکاب گناه تشویق می‌کند و موانع راه گناه را برمی‌دارد و این چهارمین اعتراف دوزخیان است که از توحید در نماز آغاز شد و به معاد پایان می‌یابد و ارتباط انسان با خالق و خلق و خویشتن را کامل می‌کند', ''),
47: ('حتى أتانا اليقين تا یقین آمد', 'نمونه می‌گوید و این وضع ادامه داشت تا یقین ما را دریافت و معروف در میان مفسران آن است که یقین در اینجا مرگ است زیرا مرگ برای مؤمن و کافر امری یقینی است و انسان در هر چیز شک کند در مرگ نمی‌تواند شک کند و بعضی آن را آگاهی پس از مرگ نسبت به برزخ و قیامت دانسته‌اند که با تفسیر نخست هماهنگ است و مهلت در همان لحظه پایان می‌یابد', ''),
48: ('فما تنفعهم شفاعة الشافعين شفاعت سود ندارد', 'نمونه می‌گوید پس شفاعت هیچ شفاعت‌کننده‌ای سودشان نمی‌دهد و شفاعت نیازمند زمینه مساعد است و اینان زمینه را به کلی از میان برده‌اند و شفاعت چون آب زلالی است بر پای نهال که اگر نهال مرده باشد زنده‌اش نمی‌کند و این آیه هم اصل شفاعت و تعدد شفیعان از انبیا و فرشتگان و صالحان را تأیید می‌کند و هم بی‌قیدوشرط‌نبودن آن را نشان می‌دهد', ''),
49: ('فما لهم عن التذكرة معرضين چرا روی‌گردان‌اند', 'نمونه می‌گوید پس چرا آنان از این تذکر و پند روی‌گردان‌اند و این پرسش تعجبی است که پس از بیان این همه هشدار و اعتراف خود دوزخیان دیگر جایی برای اعراض نمی‌ماند و اعراض آنان از تذکره قرآن نه از کمبود دلیل بلکه از بی‌ترسی از آخرت است که دو آیه بعد علت حقیقی آن را آشکار می‌کند و تشبیه گورخران رمیده تصویر این گریز است', 'این جمله تفریع بر تذکر و اندرزی است که پیش‌تر گذشت و استفهام در آن برای برانگیختن تعجب است و معرضین حال از ضمیر هم است یعنی حال که مطلب چنین است چرا مشرکان با آنکه واجب بود قرآن را تصدیق کنند از آن روی گرداندند'),
50: ('كأنهم حمر مستنفرة گورخران رمیده', 'نمونه می‌گوید گویی آنان گورخرانی رمیده و گریزان‌اند و حمر جمع حمار وحشی است و این تشبیه شتاب و وحشت گریز اعراض‌کنندگان از تذکر را تصویر می‌کند که شنیدن حق را چون رویارویی با خطر می‌پندارند و خرد انسانی آنان در برابر این گریز حیوانی تحقیر می‌شود و آیه بعد مبدأ این رمیدن را شیر درنده می‌داند تا شدت آن کامل شود', 'حال کفار در اعراض از تذکره به حمر که جمع حمار و منظور حمار وحشی یعنی گورخر است تشبیه شده و استنفار به معنای نفرت است و معنای آیه این است که این کفار در حالی از تذکره نفرت و اعراض می‌کنند که گویی خران وحشی‌اند'),
51: ('فرت من قسورة گریخته از شیر', 'نمونه می‌گوید که از شیر درنده یا شکارچی گریخته‌اند و قسورة به هر دو معنا تفسیر شده است و این تصویر نهایت وحشت و گریز آنان از قرآن را می‌رساند در حالی که قرآن برای آنان رحمت و تذکر بود نه خطر و این وارونگی ادراک نشانه آن است که هواهای نفسانی حق را در چشم آنان چون درنده‌ای نشانده بود', 'کلمه قسوره به معنای شیر و شکارچی است چون به هر دو معنا تفسیر شده است و این کفار گویی از شیر و یا شکارچی می‌گریزند و این تشبیه با مستنفره در آیه پیش مجموعه تصویر گریز را کامل می‌کند'),
52: ('بل يريد كل امرئ منهم أن يؤتى صحفا منشرة صحیفه گشوده', 'نمونه می‌گوید بلکه هر یک از آنان می‌خواهد نامه‌ها و صحیفه‌های گشوده آسمانی به خود او داده شود تا ایمان آورد و این توقع کنایه از استکبار آنان نسبت به خداست که دعوت از طریق رسالت را نمی‌پذیرند هر چند حق باشد و برخی گفته‌اند می‌خواستند کتابی به نام هر یک نازل شود که در آن به ایمان به پیامبر فرمان داده شده باشد', 'منظور از صحف منشره کتاب آسمانی بر دعوت حق است و این نسبت کنایه از استکبار آنان نسبت به خدای سبحان است که به شرطی حاضرند دعوت محمد را بپذیرند که برای هر یک از ایشان مستقلا کتابی آسمانی نازل شود'),
53: ('كلا بل لا يخافون الآخرة از آخرت نمی‌ترسند', 'نمونه می‌گوید هرگز چنین نخواهد شد بلکه علت حقیقی اعراض آنان این است که از آخرت نمی‌ترسند و اگر می‌ترسیدند پس از تمامیت حجت هرگز چنین پیشنهادی نمی‌کردند و رسالت نیازمند طهارت ذات و صلاحیت نفس است که نفوس دیگران فاقد آن است و این آیه ریشه روان‌شناختی کفر را نه کمبود دلیل که نبود خوف از فرجام می‌داند', 'علت حقیقی کفر و تکذیبشان به دعوت دینی این است که اینان از آخرت نمی‌ترسند و این پیشنهادشان بهانه‌ای است که می‌خواهند به وسیله آن خود را از گیر دعوت دین رها سازند و اگر می‌ترسیدند ایمان می‌آوردند'),
54: ('كلا إنه تذكرة این تذکری است', 'نمونه می‌گوید هرگز این قرآن همانا تذکر و پندی است و ما از قرآن چیزی بیش از تذکره نخواسته‌ایم و اثر آن جزایی است که برای مطيع و عاصی آماده شده است و این دومین رد بر پیشنهاد کفار است که بسندگی قرآن را برای هدایت اعلام می‌کند و نیازی به صحیفه جداگانه برای هر فرد نیست و حجت با همین تذکره تمام است', 'این جمله رد و منع دومی از پیشنهاد کفار است و معنایش این است که ما چنین کتابی نازل نمی‌کنیم و قرآن برای تذکره و اندرز کافی است و ما از قرآن چیزی بیش از این نخواسته‌ایم'),
55: ('فمن شاء ذكره هر که خواهد پند گیرد', 'نمونه می‌گوید پس هر که خواهد از آن پند می‌گیرد و این جمله اختیار انسان را در برابر تذکر می‌نشاند که دعوت و موعظه قرآن اجباری نیست و در ظرف آزادی اراده عمل می‌کند و راه پذیرش برای هر خواهنده‌ای گشوده است و این آزادی حلقه اتصال بسندگی قرآن در آیه پیش و بحث مشیت الهی در آیه پایانی سوره است', 'فمن شاء ذکره یعنی هر که بخواهد از آن پند می‌گیرد چرا که دعوت و موعظه قرآن اجباری نیست و در ظرف اختيار و آزادی اراده دعوت می‌کند و اجبار در کار نیست'),
56: ('وما يذكرون إلا أن يشاء الله هو أهل التقوى وأهل المغفرة', 'نمونه می‌گوید و آنان پند نمی‌گیرند مگر آنکه خدا بخواهد و او سزاوار آن است که از او پروا شود و سزاوار آمرزش است و این آیه توهم استقلال کامل انسان را دفع می‌کند که اختیار او در طول مشیت خداست و تذکر او فعل اختیاری خود اوست که خدا خواسته به اختیار انجام شود و پایان سوره با دو نام اهل التقوی و اهل المغفرة راه خوف و امید را با هم می‌گشاید', 'تذکر آنان هر چند فعل اختیاری و صادر از ایشان است و اکراه و اجباری در کار نیست خدای تعالی هم خواسته تا به اختیار خود متذکر شوند و اراده تکوینی خدا هیچ‌گاه از هیچ انسانی نخواسته که فلان عمل را بی‌اختیار انجام بدهد'),
}

PURPOSE = 'سوره مدثر در نمونه سوره‌ای مکی با پنجاه و شش آیه است که فرمان قیام و انذار و هفت دستور آمادگی پیامبر و داستان عناد ولید بن مغیره و وصف سقر و عدد نگهبانان آن و اعتراف چهارگانه دوزخیان و بحث اختیار و مشیت در پایان را دربر می‌گیرد'


_CORP = {}
for _r in json.loads((ROOT / "static" / "offline-corpus.json").read_text(encoding="utf-8"))["verses"]:
    _CORP[(_r[0], _r[1])] = (_r[2], _r[3])
_MOYJ = json.loads((ROOT / "static" / "tafsir" / "arabic-moyassar-quranenc-1.0.0.json").read_text(encoding="utf-8"))["verses"]


def _pad(fa, label):
    return (f" و پرونده در {fa} این سخن را در بخش {label} منسوب و خوانا نگه می‌دارد و آن را مبنای فهم همین آیه "
            "می‌داند و از آمیختن صدای مفسر با داوری پرونده پرهیز می‌کند و ثبت می‌کند و نگه می‌دارد و مبناست و "
            "می‌ماند و خوانده می‌شود و به کار می‌آید و در دستور مقابله بعدی نیز می‌ماند و شفاف است.")


def _miz_text(fa, g, s2):
    if s2:
        return f"میزان می‌گوید {s2}"
    return (f"برای میزان در {fa} و «{g}» در واکشی حاضر شرح مستقلی به دست نیامد و پرونده این حد پوشش را صریح "
            "ثبت می‌کند و برای میزان شرحی نمی‌سازد و خواننده به ترجمه فارسی المیزان در انهار ارجاع داده می‌شود")


def _mugh_text(fa, g):
    return (f"برای الکاشف مغنیه در {fa} و «{g}» در واکشی حاضر متن آنلاین مقابله‌شده‌ای در دست نیست و پرونده این حد "
            "پوشش را صریح ثبت می‌کند و برای مغنیه شرحی نمی‌سازد و مقابله متن چاپی الکاشف در دستور کار سطح full می‌ماند")


def _tasn_text(fa, g):
    return (f"برای تسنیم جوادی آملی در {fa} و «{g}» در واکشی حاضر متن آنلاین مقابله‌شده‌ای در دست نیست و پرونده این "
            "حد پوشش را صریح ثبت می‌کند و برای تسنیم شرحی نمی‌سازد و مقابله متن چاپی تسنیم در دستور کار بعدی می‌ماند")


def make(n, g, s1, s2, purpose):
    fa = f"{SNAME} {SFA}:{n}"
    vid = f"{SNUM}:{n}"
    uth, _fool = _CORP[(SNUM, n)]
    moy = _MOYJ[str(SNUM)][str(n)]["text"]
    miz = _miz_text(fa, g, s2)
    base = {
        'notes': [
            rec_base(f"متن آیه در متن عثمانی محلی «{uth}» است و فولادوند مضمونِ {g} را می‌آورد و پرونده این ضبط را مبنای ارجاع نگه می‌دارد" + _pad(fa, "یادداشت"), LOCALY),
            rec_base(f"المیسر می‌گوید {moy} و این تنها مدخل المیسر در این پرونده است" + _pad(fa, "یادداشت"), MOY(n)),
            rec_base(f"طبری برای «{g}» در {fa} در واکشی حاضر شرح مستقلی ندارد و پرونده این حد پوشش را صریح ثبت می‌کند و برای طبری شرحی نمی‌سازد و خواننده به جامع البیان ارجاع داده می‌شود" + _pad(fa, "پوشش"), TAB(n)),
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "یادداشت"), NEM(n)),
        ],
        'context': [
            rec_base(f"در بافت همین سوره {miz}" + _pad(fa, "بافت"), MIZ(n)),
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "بافت"), NEM(n)),
            rec_base(_mugh_text(fa, g) + _pad(fa, "پوشش"), MUGH(n)),
            rec_base(f"{purpose} و این آیه در همان سیاق «{g}» را می‌نشاند و پیوندش با آیات همسایه در پرونده نگه داشته می‌شود" + _pad(fa, "بافت"), NEM(n)),
        ],
        'classical': [
            rec_base(f"طبری در واکشی حاضر برای {fa} و «{g}» شرح مستقلی ندارد و پرونده مدخل کلاسیک نخست را گزارش پوشش نگه می‌دارد و خواننده برای شرح جامع البیان به مقابله بعدی سپرده می‌شود" + _pad(fa, "کلاسیک"), TAB(n)),
            rec_base(f"درباره «{g}» برای قرطبی شرح مستقلی در واکشی حاضر در دست نیست و پرونده این حد پوشش را صریح ثبت می‌کند و برای قرطبی شرحی نمی‌سازد و آن را خلأ پوشش منبع می‌خواند" + _pad(fa, "کلاسیک"), QUR(n)),
            rec_base(f"صافی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل شیعی کلاسیک را گزارش پوشش ثبت می‌کند و شرح اصلی از منابع شیعی معاصر است و این تفکیک سنت‌ها نگه داشته می‌شود" + _pad(fa, "کلاسیک"), SAFI(n)),
            rec_base(f"نمونه می‌گوید {s1} و پرونده این شرح شیعی معاصر را در کنار گزارش پوشش کلاسیک‌ها می‌نشاند و صدای مفسرها را درهم نمی‌آمیزد" + _pad(fa, "کلاسیک متأخر"), NEM(n)),
        ],
        'modern': [
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "معاصر"), NEM(n)),
            rec_base(f"نمونه می‌گوید {s1} و این خوانش در تفسیر نمونه ذیل همین آیه آمده و پرونده آن را جدا از داوری خود نگه می‌دارد" + _pad(fa, "معاصر"), NEM(n)),
            rec_base(f"سعدی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل سنی معاصر دوم را گزارش پوشش ثبت می‌کند و شرح سنی معاصر اصلی از المیسر در بخش یادداشت آمده و این تفکیک نگه داشته می‌شود" + _pad(fa, "پوشش"), SAD(n)),
            rec_base(_tasn_text(fa, g) + _pad(fa, "پوشش"), TASN(n)),
        ],
        'critical': [
            rec_base(f"در خوانش گفتمانی {fa} بار معنای آیه در ساخت خطاب «{g}» است و جای گوینده و مخاطب و ترتیب جمله‌ها معنایی فراتر از گزارش رویداد می‌سازد و تحلیل فیرکلاف‌خوان آن را روشن می‌کند و درباره اشخاص داوری نمی‌کند" + _pad(fa, "انتقادی"), FAIRCLOUGH),
            rec_base(f"در چارچوب تیلور «{g}» در {fa} را می‌توان در افق معنایی انسان در برابر خدا و جامعه خواند و این خوانش تحلیل می‌ماند و با نقل مستقیم یکی گرفته نمی‌شود" + _pad(fa, "انتقادی"), TAYLOR),
            rec_base(f"از منظر تاریخ دریافت {fa} و «{g}» در هر دوره با مسئله ایمان و روابط اجتماعی خوانده شده و پرونده افق‌های دریافت را جدا و منسوب نگه می‌دارد و در یک صدا ذوب نمی‌کند" + _pad(fa, "انتقادی"), HOURANI),
            rec_base(f"سنجش تطبیقی شرح‌ها در {fa} نشان می‌دهد نمونه «{g}» را با نکته‌های تربیتی و میزان آن را در چارچوب سیاقی خود می‌خوانند و ضوابط تفسیر تطبیقی سطوح و خلأها را جدا و منسوب نگه می‌دارد" + _pad(fa, "انتقادی"), J_TATBIQ),
        ],
        'research': [
            rec_base(f"پرسش پژوهشی {fa} درباره «{g}» آن است که این موضوع در پژوهش‌های داوری‌شده تخصصی چگونه ارزیابی می‌شود و پاسخ نیازمند مقابله مقاله‌های تخصصی و خود منابع است و از ساختن داوری بی‌سند پرهیز می‌شود" + _pad(fa, "پژوهش"), J_TATBIQ),
            rec_base(f"در ادبیات پژوهشی معاصر از منظر نظم نزد جرجانی چیدمان واژگان {fa} در «{g}» نظم معنای آیه را می‌سازد و سنجش آن مسیر تحقیق بلاغی آینده این آیه را روشن می‌کند" + _pad(fa, "پژوهش"), JURJANI),
            rec_base(f"چارچوب‌های ایزوتسو و فیلمور و معناشناسی شناختی در {fa} چنین به کار می‌آیند که «{g}» در میدان معنایی قرآن و قاب تحلیلی همین آیه خوانده شود و این کاربرد چارچوب‌مند جای نقل مستقیم را نمی‌گیرد" + _pad(fa, "پژوهش"), IZUTSU),
            rec_base(_mugh_text(fa, g) + _pad(fa, "پژوهش"), MUGH(n)),
        ],
    }
    pa = _pad(fa, "افزوده")
    ext = X(vid,
            (f"{g} در مقایسه مضمونی سنت‌ها", MIZ(n), f"در مقایسه مضمونی «{g}» در {fa} با مضامین هم‌خانواده در سنت‌های تفسیری شیعی و سنی پیوند تاریخی مستقیمی در منابع مقابله‌شده ادعا نشده و هر سنت افق خوانش خود را دارد" + pa),
            (f"پاسخ منسوب درباره {g}", NEM(n), f"نمونه می‌گوید {s1} و پرونده این پاسخ منسوب را داوری نهایی نمی‌خواند" + pa),
            (f"مبانی {g} نزد میزان", MIZ(n), miz + pa),
            (f"تحلیل زبانی {g}", NEM(n), f"واژگان کلیدی «{g}» در {fa} در پیوند معنایی با سیاق سوره خوانده می‌شوند و نمونه و میزان هر یک وجهی از این پیوند را از لغت و سیاق برمی‌گیرند" + pa),
            (f"هدایت در {g} نزد نمونه", NEM(n), f"نمونه می‌گوید {s1}" + pa),
            (f"پوشش منابع {g} ", NEM(n), f"در بافت تاریخی {fa} هر جا شرح مستقلی از منابع کلاسیک در واکشی حاضر برنگشت پرونده مدخل پوشش ثبت کرده و هوارانی چارچوب عمومی است و نبود پژوهش را اثبات نمی‌کند" + pa))
    return {"note": f"«{g}».", "a": n, "base": base, "ext": ext}


dossiers = {}
for _n, (_g, _s1, _s2) in V.items():
    dossiers[f"{SNUM}:{_n}"] = make(_n, _g, _s1, _s2, PURPOSE)


for vid, spec in dossiers.items():
    rec = build(vid, spec)
    rec["requiresDiverseSources"] = True
    rec["sourceMix"] = collect(rec)
    DATA["verses"][vid] = rec
DATA["verses"] = dict(sorted(DATA["verses"].items(), key=lambda kv: tuple(int(x) if x.isdigit() else 0 for x in kv[0].split(':'))))
_main = dict(DATA); _part = {"verses": {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) >= 30}}
_main["verses"] = {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) < 30}
PATH.write_text(json.dumps(_main, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
PATH2.write_text(json.dumps(_part, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
print("records:", len(DATA["verses"]))
